import sys
import json
from decimal import Decimal, ROUND_HALF_UP
from collections import defaultdict

def solve():
    if len(sys.argv) < 2:
        return

    input_filename = sys.argv[1]

    category_totals = defaultdict(Decimal)
    grand_total = Decimal("0.00")

    try:
        with open(input_filename, mode='r', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)

            for row in reader:
                # Check status
                status = row.get('status', '').strip().casefold()
                if status == 'paid':
                    # Normalize category
                    raw_category = row.get('category', '')
                    # Collapse whitespace and casefold
                    normalized_category = " ".join(raw_category.split()).casefold()
                    if not normalized_category:
                        normalized_category = "uncategorized"

                    # Parse and round amount
                    try:
                        amount_str = row.get('amount', '0')
                        amount = Decimal(amount_str)
                        rounded_amount = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
                    except Exception:
                        # If amount is invalid, we'll assume 0 or handle error. 
                        # Given the prompt, we assume valid amount strings.
                        rounded_amount = Decimal("0.00")

                    category_totals[normalized_category] += rounded_amount
                    grand_total += rounded_amount
    except FileNotFoundError:
        # Should not happen based on problem description
        pass
    except Exception:
        pass

    # Prepare output
    sorted_categories = sorted(category_totals.keys())
    categories_list = []
    for cat in sorted_categories:
        categories_list.append({
            "category": cat,
            "total": f"{category_totals[cat]:.2f}"
        })

    output = {
        "categories": categories_list,
        "total": f"{grand_total:.2f}"
    }

    print(json.dumps(output))

if __name__ == "__main__":
    solve()
"}

